- Bindings and error handling in serverless architectures

## Code Example
```javascript
module.exports = async function(context, req) {
  const body = req.body;
  // basic validation
  if (!body?.userId || !body?.eventType || !body?.timestamp) {
    context.res = { status: 400, body: 'Invalid payload' };
    return;
  }
  const id = `${body.userId}|${body.timestamp}`;
  // write summary to Cosmos DB (idempotent key)
  context.bindings.cosmosDoc = { id, userId: body.userId, timestamp: body.timestamp, eventType: body.eventType };
  // publish raw event to Event Hubs
  context.bindings.outputEventHub = body;
  context.res = { status: 202, body: 'Accepted' };
};
```

